def choose(pool,weights,seed):
 bands=[[],[],[]]
 for entity,band in sorted(set(pool)):bands[band].append(entity)
 d=hashlib.sha256(('course-academy/question-selection/v1/'+seed).encode()).digest()
 def unif(o):return (int.from_bytes(d[o:o+8],'big')>>11)/2**53
 total=sum(w for i,w in enumerate(weights) if bands[i]);draw=unif(0)*total;chosen=None
 for i,w in enumerate(weights):
  if not bands[i] or w==0:continue
  chosen=i
  if draw<w:break
  draw-=w
 return None if chosen is None else bands[chosen][int(unif(8)*len(bands[chosen]))]
